INSERT INTO tutor_questions (id, topic_id, type, freq, text, options, ref, answer, hint, steps, sort_order) SELECT 'st1', id, 'Prizma', 6, 'Düzgün dördbucaqlı prizmanın oturacağının tərəfi 3, hündürlüyü 5-dir. Prizmanın tam səthinin sahəsini tapın.', '{"A":"60","B":"69","C":"78","D":"84","E":"45"}', '2025 toplu, II hissə, səh.210 №4–9', 'C', 'Tam səth = iki oturacaq + yan səth. Yan səth = oturacağın perimetri × hündürlük.', '["Oturacaqlar: $2 \\cdot 3^2 = 18$.","Yan səth: $P \\cdot h = 4 \\cdot 3 \\cdot 5 = 60$.","Tam səth: $18 + 60 =$ **78**."]', 1 FROM topics WHERE slug = 'stereometriya';--> statement-breakpoint
INSERT INTO tutor_questions (id, topic_id, type, freq, text, options, ref, answer, hint, steps, sort_order) SELECT 'st2', id, 'Piramida', 5, 'Düzgün dördbucaqlı piramidanın oturacağının tərəfi 6, hündürlüyü 4-dür. Piramidanın həcmini tapın.', '{"A":"144","B":"48","C":"72","D":"24","E":"96"}', '2025 toplu, II hissə, səh.214 №1–6', 'B', 'Piramidanın həcmi oturacağın sahəsi ilə hündürlüyün hasilinin üçdə biridir.', '["Oturacağın sahəsi: $S = 6^2 = 36$.","$V = \\frac{1}{3} S h = \\frac{1}{3} \\cdot 36 \\cdot 4 =$ **48**."]', 2 FROM topics WHERE slug = 'stereometriya';--> statement-breakpoint
INSERT INTO tutor_questions (id, topic_id, type, freq, text, options, ref, answer, hint, steps, sort_order) SELECT 'st3', id, 'Silindr', 5, 'Silindrin ox kəsiyi tərəfi 4 olan kvadratdır. Silindrin həcmini tapın.', '{"A":"$8\\pi$","B":"$16\\pi$","C":"$32\\pi$","D":"$64\\pi$","E":"$4\\pi$"}', '2023 toplu, II hissə, səh.176 №2–8', 'B', 'Ox kəsiyi kvadratdırsa, diametr hündürlüyə bərabərdir: $2R = h$.', '["$2R = 4$, deməli $R = 2$, $h = 4$.","$V = \\pi R^2 h = \\pi \\cdot 4 \\cdot 4 =$ **$16\\pi$**."]', 3 FROM topics WHERE slug = 'stereometriya';--> statement-breakpoint
INSERT INTO tutor_questions (id, topic_id, type, freq, text, options, ref, answer, hint, steps, sort_order) SELECT 'st4', id, 'Kürə', 4, 'Kürənin həcmi $36\pi$-dir. Kürənin radiusunu tapın.', '{"A":"2","B":"3","C":"4","D":"6","E":"9"}', '2023 toplu, II hissə, səh.182 №1–5', 'B', '$V = \frac{4}{3}\pi R^3$ düsturundan $R^3$-u tap.', '["$\\frac{4}{3}\\pi R^3 = 36\\pi \\Rightarrow R^3 = 27$.","$R =$ **3**."]', 4 FROM topics WHERE slug = 'stereometriya';--> statement-breakpoint
INSERT INTO tutor_questions (id, topic_id, type, freq, text, options, ref, answer, hint, steps, sort_order) SELECT 'lt1', id, 'Törəmə', 6, '$f(x) = x^3 - 4x$ olarsa, $f''(2)$-ni tapın.', '{"A":"4","B":"8","C":"12","D":"0","E":"16"}', '2025 toplu, I hissə, səh.180 №1–8', 'B', 'Qüvvətin törəməsi: $(x^n)'' = n x^{n-1}$.', '["$f''(x) = 3x^2 - 4$.","$f''(2) = 3 \\cdot 4 - 4 =$ **8**."]', 1 FROM topics WHERE slug = 'limit-toreme-inteqral';--> statement-breakpoint
INSERT INTO tutor_questions (id, topic_id, type, freq, text, options, ref, answer, hint, steps, sort_order) SELECT 'lt2', id, 'Toxunanın bucaq əmsalı', 4, '$y = x^2 + 3x$ funksiyasının qrafikinə absisi $x_0 = 1$ olan nöqtədə çəkilmiş toxunanın bucaq əmsalını tapın.', '{"A":"4","B":"5","C":"3","D":"2","E":"6"}', '2025 toplu, I hissə, səh.184 №2–7', 'B', 'Toxunanın bucaq əmsalı toxunma nöqtəsindəki törəməyə bərabərdir.', '["$y'' = 2x + 3$.","$k = y''(1) = 2 + 3 =$ **5**."]', 2 FROM topics WHERE slug = 'limit-toreme-inteqral';--> statement-breakpoint
INSERT INTO tutor_questions (id, topic_id, type, freq, text, options, ref, answer, hint, steps, sort_order) SELECT 'lt3', id, 'Müəyyən inteqral', 5, '$\int_0^2 3x^2\,dx$ inteqralını hesablayın.', '{"A":"6","B":"8","C":"12","D":"4","E":"24"}', '2025 toplu, I hissə, səh.192 №1–6', 'B', '$3x^2$ funksiyasının ibtidai funksiyası $x^3$-dur.', '["İbtidai funksiya: $F(x) = x^3$.","$F(2) - F(0) = 8 - 0 =$ **8**."]', 3 FROM topics WHERE slug = 'limit-toreme-inteqral';--> statement-breakpoint
INSERT INTO tutor_questions (id, topic_id, type, freq, text, options, ref, answer, hint, steps, sort_order) SELECT 'lt4', id, 'Limit', 3, '$\lim\limits_{x \to 3} \frac{x^2 - 9}{x - 3}$ limitini tapın.', '{"A":"0","B":"3","C":"6","D":"9","E":"Limit yoxdur"}', '2023 toplu, I hissə, səh.150 №1–5', 'C', 'Surəti vuruqlara ayır: $x^2 - 9 = (x - 3)(x + 3)$.', '["$\\frac{(x - 3)(x + 3)}{x - 3} = x + 3$, $x \\ne 3$.","$\\lim\\limits_{x \\to 3} (x + 3) =$ **6**."]', 4 FROM topics WHERE slug = 'limit-toreme-inteqral';--> statement-breakpoint
INSERT INTO tutor_questions (id, topic_id, type, freq, text, options, ref, answer, hint, steps, sort_order) SELECT 'lg1', id, 'Üstlü tənliklər', 6, '$3^{2x - 1} = 27$ tənliyini həll edin.', '{"A":"1","B":"2","C":"3","D":"$\\frac{1}{2}$","E":"4"}', '2025 toplu, I hissə, səh.114 №2–9', 'B', '27-ni 3-ün qüvvəti kimi yaz.', '["$27 = 3^3$, deməli $2x - 1 = 3$.","$x =$ **2**."]', 1 FROM topics WHERE slug = 'loqarifm-ustlu-tenlik-berabersizlik';--> statement-breakpoint
INSERT INTO tutor_questions (id, topic_id, type, freq, text, options, ref, answer, hint, steps, sort_order) SELECT 'lg2', id, 'Loqarifmik tənliklər', 5, '$\lg x + \lg 4 = 2$ tənliyini həll edin.', '{"A":"25","B":"50","C":"96","D":"20","E":"4"}', '2025 toplu, I hissə, səh.112 №1–6', 'A', 'Loqarifmlərin cəmi hasilin loqarifmidir; $\lg$ — 10 əsaslı loqarifmdir.', '["$\\lg (4x) = 2 \\Rightarrow 4x = 10^2 = 100$.","$x =$ **25** (yoxlama: $x > 0$)."]', 2 FROM topics WHERE slug = 'loqarifm-ustlu-tenlik-berabersizlik';--> statement-breakpoint
INSERT INTO tutor_questions (id, topic_id, type, freq, text, options, ref, answer, hint, steps, sort_order) SELECT 'lg3', id, 'Üstlü bərabərsizliklər', 4, '$2^x > 8$ bərabərsizliyini həll edin.', '{"A":"$x > 3$","B":"$x < 3$","C":"$x > 4$","D":"$x \\ge 3$","E":"$x > 8$"}', '2023 toplu, I hissə, səh.78 №1–7', 'A', 'Əsas 1-dən böyükdürsə, bərabərsizliyin işarəsi dəyişmir.', '["$8 = 2^3$: $2^x > 2^3$.","Əsas $2 > 1$, ona görə **$x > 3$**."]', 3 FROM topics WHERE slug = 'loqarifm-ustlu-tenlik-berabersizlik';--> statement-breakpoint
INSERT INTO tutor_questions (id, topic_id, type, freq, text, options, ref, answer, hint, steps, sort_order) SELECT 'lg4', id, 'Loqarifmik bərabərsizliklər', 3, '$\log_{\frac{1}{2}} x > -2$ bərabərsizliyini həll edin.', '{"A":"$x > 4$","B":"$0 < x < 4$","C":"$x < 4$","D":"$x > 0$","E":"$0 < x < \\frac{1}{4}$"}', '2023 toplu, I hissə, səh.80 №2–8', 'B', 'Əsas 1-dən kiçikdir — işarə dəyişir. Təyin oblastını unutma: $x > 0$.', '["$-2 = \\log_{\\frac{1}{2}} 4$.","Əsas $\\frac{1}{2} < 1$, ona görə $x < 4$.","Təyin oblastı ilə: **$0 < x < 4$**."]', 4 FROM topics WHERE slug = 'loqarifm-ustlu-tenlik-berabersizlik';--> statement-breakpoint
INSERT INTO tutor_questions (id, topic_id, type, freq, text, options, ref, answer, hint, steps, sort_order) SELECT 'tr1', id, 'Gətirmə düsturları', 5, '$\sin 210^\circ$ ifadəsinin qiymətini tapın.', '{"A":"$\\frac{1}{2}$","B":"$-\\frac{1}{2}$","C":"$\\frac{\\sqrt{3}}{2}$","D":"$-\\frac{\\sqrt{3}}{2}$","E":"$-1$"}', '2025 toplu, I hissə, səh.97 №1–8', 'B', '$210^\circ = 180^\circ + 30^\circ$; III rübdə sinus mənfidir.', '["$\\sin(180^\\circ + \\alpha) = -\\sin\\alpha$.","$\\sin 210^\\circ = -\\sin 30^\\circ =$ **$-\\frac{1}{2}$**."]', 1 FROM topics WHERE slug = 'triqonometriya';--> statement-breakpoint
INSERT INTO tutor_questions (id, topic_id, type, freq, text, options, ref, answer, hint, steps, sort_order) SELECT 'tr2', id, 'Əsas eynilik', 6, '$\cos\alpha = -\frac{3}{5}$ və $90^\circ < \alpha < 180^\circ$. $\operatorname{tg}\alpha$-nı tapın.', '{"A":"$\\frac{4}{3}$","B":"$-\\frac{4}{3}$","C":"$-\\frac{3}{4}$","D":"$\\frac{3}{4}$","E":"$-\\frac{4}{5}$"}', '2025 toplu, I hissə, səh.94 №2–8', 'B', 'Əvvəl $\sin\alpha$-nı tap; II rübdə sinus müsbətdir.', '["$\\sin\\alpha = \\sqrt{1 - \\frac{9}{25}} = \\frac{4}{5}$ (II rüb).","$\\operatorname{tg}\\alpha = \\frac{\\sin\\alpha}{\\cos\\alpha} = \\frac{4}{5} : \\left(-\\frac{3}{5}\\right) =$ **$-\\frac{4}{3}$**."]', 2 FROM topics WHERE slug = 'triqonometriya';--> statement-breakpoint
INSERT INTO tutor_questions (id, topic_id, type, freq, text, options, ref, answer, hint, steps, sort_order) SELECT 'tr3', id, 'Triqonometrik tənliklər', 4, '$2\cos x = 1$ tənliyinin $(0^\circ; 90^\circ)$ aralığındakı həllini tapın.', '{"A":"$30^\\circ$","B":"$45^\\circ$","C":"$60^\\circ$","D":"$90^\\circ$","E":"$15^\\circ$"}', '2023 toplu, II hissə, səh.91 №1–6', 'C', 'Əvvəl $\cos x$-i tap, sonra əsas bucaqlar cədvəlinə bax.', '["$\\cos x = \\frac{1}{2}$.","$(0^\\circ; 90^\\circ)$ aralığında $x =$ **$60^\\circ$**."]', 3 FROM topics WHERE slug = 'triqonometriya';--> statement-breakpoint
INSERT INTO tutor_questions (id, topic_id, type, freq, text, options, ref, answer, hint, steps, sort_order) SELECT 'tr4', id, 'İkiqat bucaq düsturları', 4, '$\cos^2 15^\circ - \sin^2 15^\circ$ ifadəsinin qiymətini tapın.', '{"A":"$\\frac{1}{2}$","B":"$\\frac{\\sqrt{3}}{2}$","C":"1","D":"$\\frac{\\sqrt{2}}{2}$","E":"0"}', '2023 toplu, II hissə, səh.88 №3–9', 'B', '$\cos^2\alpha - \sin^2\alpha$ — ikiqat bucağın kosinusudur.', '["$\\cos^2\\alpha - \\sin^2\\alpha = \\cos 2\\alpha$.","$\\cos 30^\\circ =$ **$\\frac{\\sqrt{3}}{2}$**."]', 4 FROM topics WHERE slug = 'triqonometriya';--> statement-breakpoint
INSERT INTO tutor_questions (id, topic_id, type, freq, text, options, ref, answer, hint, steps, sort_order) SELECT 'uc1', id, 'Oxşar üçbucaqlar', 5, 'İki oxşar üçbucağın oxşarlıq əmsalı 3-dür. Kiçik üçbucağın sahəsi 5-dirsə, böyük üçbucağın sahəsini tapın.', '{"A":"15","B":"45","C":"25","D":"75","E":"9"}', '2025 toplu, II hissə, səh.160 №1–7', 'B', 'Oxşar fiqurların sahələrinin nisbəti oxşarlıq əmsalının kvadratına bərabərdir.', '["$\\frac{S_2}{S_1} = k^2 = 9$.","$S_2 = 5 \\cdot 9 =$ **45**."]', 1 FROM topics WHERE slug = 'ucbucaqlar';--> statement-breakpoint
INSERT INTO tutor_questions (id, topic_id, type, freq, text, options, ref, answer, hint, steps, sort_order) SELECT 'uc2', id, 'Sinuslar teoremi', 4, 'Üçbucaqda $a = 10$, ona qarşı bucaq $30^\circ$-dir. Üçbucağa xaricdən çəkilmiş çevrənin radiusunu tapın.', '{"A":"5","B":"10","C":"20","D":"$5\\sqrt{3}$","E":"$10\\sqrt{3}$"}', '2023 toplu, II hissə, səh.133 №1–6', 'B', 'Sinuslar teoremi: $\frac{a}{\sin A} = 2R$.', '["$\\frac{10}{\\sin 30^\\circ} = 2R$.","$2R = 20$, $R =$ **10**."]', 2 FROM topics WHERE slug = 'ucbucaqlar';--> statement-breakpoint
INSERT INTO tutor_questions (id, topic_id, type, freq, text, options, ref, answer, hint, steps, sort_order) SELECT 'uc3', id, 'Pifaqor teoremi', 6, 'Bərabəryanlı üçbucağın yan tərəfi 13, oturacağı 10-dur. Oturacağa endirilmiş hündürlüyü tapın.', '{"A":"12","B":"8","C":"$\\sqrt{69}$","D":"11","E":"13"}', '2025 toplu, II hissə, səh.154 №2–9', 'A', 'Hündürlük oturacağı yarıya bölür — düzbucaqlı üçbucaq alınır.', '["Oturacağın yarısı: $10 : 2 = 5$.","$h = \\sqrt{13^2 - 5^2} = \\sqrt{144} =$ **12**."]', 3 FROM topics WHERE slug = 'ucbucaqlar';--> statement-breakpoint
INSERT INTO tutor_questions (id, topic_id, type, freq, text, options, ref, answer, hint, steps, sort_order) SELECT 'uc4', id, 'Üçbucağın sahəsi', 5, 'Tərəfləri 5, 5 və 6 olan üçbucağın sahəsini tapın.', '{"A":"12","B":"15","C":"24","D":"30","E":"10"}', '2025 toplu, II hissə, səh.158 №1–6', 'A', 'Üçbucaq bərabəryanlıdır: 6 olan tərəfə hündürlük endir.', '["Hündürlük: $h = \\sqrt{5^2 - 3^2} = 4$.","$S = \\frac{1}{2} \\cdot 6 \\cdot 4 =$ **12**."]', 4 FROM topics WHERE slug = 'ucbucaqlar';
